import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/index.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports a thrown string with its cause and preserves the caller rejection', async () => {
  const failures: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeUserInput: () => Promise.reject('input rejected'),
        onError: async (_session, error) => void failures.push(error),
      },
    }
  );

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({failures, cause: failures[0]?.cause, rejection}).toEqual({
    failures: [new Error('input rejected')],
    cause: 'input rejected',
    rejection: 'input rejected',
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/chatOrchestrator.rejection.test.ts --runInBand"

